import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import LanguageDetector from "i18next-browser-languagedetector";
import en from "./locales/en.json";
import es from "./locales/es.json";

// Single source of truth for the whole app's language.
// Detection order: saved choice (localStorage) -> browser language.
// If neither maps to a supported language, we fall back to English (Anglo market).
i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: {
      en: { translation: en },
      es: { translation: es },
    },
    fallbackLng: "en",
    supportedLngs: ["en", "es"],
    load: "languageOnly", // es-MX -> es, en-US -> en
    nonExplicitSupportedLngs: true,
    interpolation: { escapeValue: false },
    detection: {
      order: ["localStorage", "navigator"],
      lookupLocalStorage: "unitech_lang",
      caches: ["localStorage"],
    },
  });

export default i18n;
